"use client";

import { useState } from "react";
import { Trash2, ArrowLeft, Plus, Lock } from "lucide-react"; // Lock ikonu ekledik
import { Button } from "@/components/ui/button";
import TaskFormModal from "./TaskFormModal";
import { deleteTask, updateTaskContent } from "@/app/actions/task-actions";
import SmartField from "./SmartField";

export default function TaskListClient({ initialTasks, isReadOnly }: { initialTasks: any[], isReadOnly: boolean }) {
  const [open, setOpen] = useState(false);
  const [geselecteerdItem, setGeselecteerdItem] = useState<any | null>(null);

  return (
    <div className="min-h-screen bg-[#070B24] text-teal-200 py-10 px-8 flex flex-col items-center w-full">
      {/* Modal sadece yetkiliye açılır */}
      {!isReadOnly && <TaskFormModal open={open} setOpen={setOpen} />}
      
      <div className="w-full max-w-7xl">
        <div className="flex justify-between items-end mb-8 border-b border-teal-500/10 pb-6">
          <div>
            <h1 className="text-4xl font-black text-white italic tracking-tighter uppercase">Scrum Dashboard</h1>
            <p className="text-teal-500/50 text-[10px] font-bold tracking-[0.4em] mt-2 underline decoration-fuchsia-500/50 underline-offset-8 uppercase">
              {isReadOnly ? "Gastmodus (Alleen Lezen)" : "Engine v2.0"}
            </p>
          </div>

          {/* Buton Görünür Ama Tıklanamaz */}
          <Button 
            onClick={() => !isReadOnly && setOpen(true)} 
            disabled={isReadOnly}
            className={`font-black px-8 py-6 rounded-none skew-x-[-12deg] transition-all ${
              isReadOnly 
                ? "bg-gray-500/20 text-gray-500 cursor-not-allowed border border-gray-500/20" 
                : "bg-fuchsia-600 hover:bg-fuchsia-500 text-white"
            }`}
          >
            <Plus className="mr-2 skew-x-[12deg]" /> 
            <span className="skew-x-[12deg]">{isReadOnly ? "LOG IN OM TE VOEGEN" : "NIEUW DOCUMENT"}</span>
          </Button>
        </div>

        {!geselecteerdItem ? (
          <div className="bg-[#0E153A]/40 backdrop-blur-xl border border-teal-500/20 rounded-2xl overflow-hidden shadow-2xl">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-teal-500/5 text-teal-500 text-[10px] font-black uppercase tracking-[0.2em]">
                  <th className="px-8 py-5">Type</th>
                  <th>Document Naam</th>
                  <th>Sprint</th>
                  <th>Datum</th>
                  <th className="text-right px-8">Actie</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-teal-500/5">
                {initialTasks.map((task) => {
                  let data; try { data = JSON.parse(task.description || "{}"); } catch { data = {}; }
                  return (
                    <tr 
                      key={task.id} 
                      onClick={() => setGeselecteerdItem({ ...data, id: task.id })} 
                      className="group hover:bg-teal-500/5 cursor-pointer transition-colors"
                    >
                      <td className="px-8 py-6">
                        <span className="bg-fuchsia-500/10 text-fuchsia-400 text-[10px] font-black px-2 py-1 rounded border border-fuchsia-500/20 uppercase">
                          {data.documentType}
                        </span>
                      </td>
                      <td className="font-bold text-teal-50 group-hover:text-fuchsia-300">{task.title}</td>
                      <td className="font-mono text-teal-400/70">S-{data.sprint}</td>
                      <td className="text-xs text-teal-400/50">{data.datum}</td>
                      <td className="text-right px-8">
                        <button 
                          disabled={isReadOnly}
                          onClick={(e) => { 
                            e.stopPropagation(); 
                            if(!isReadOnly) deleteTask(task.id); 
                          }} 
                          className={`p-2 transition-all ${isReadOnly ? "text-gray-700 cursor-not-allowed" : "text-teal-900 hover:text-red-500"}`}
                        >
                          {isReadOnly ? <Lock size={16} /> : <Trash2 size={18} />}
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="animate-in slide-in-from-bottom-10 duration-500">
            <button onClick={() => setGeselecteerdItem(null)} className="flex items-center text-fuchsia-400 font-black text-xs tracking-widest mb-8 hover:text-white transition-colors uppercase">
              <ArrowLeft size={16} className="mr-2" /> Terug naar overzicht
            </button>
            <div className="bg-[#0E153A]/60 backdrop-blur-2xl border border-teal-400/30 p-16 rounded-3xl relative">
              {/* Düzenleme Alanları Burada Gelecek (SmartField kullanıyor) */}
              <div className="max-w-3xl mx-auto text-center">
                 <h2 className="text-4xl font-black text-white uppercase italic">{geselecteerdItem.titel}</h2>
                 {isReadOnly && <p className="text-fuchsia-500 text-[10px] mt-2 font-bold italic">MODUS ALLEEN LEZEN - LOG IN OM TE BEWERKEN</p>}
              </div>
              {/* Örnek SmartField kullanımı */}
              <SmartField 
                isReadOnly={isReadOnly} 
                label="INHOUD" 
                value={geselecteerdItem.geleerd || ""} 
                onSave={(v) => !isReadOnly && updateTaskContent(geselecteerdItem.id, { ...geselecteerdItem, geleerd: v })} 
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}