"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth"; 
import { authOptions } from "@/app/api/auth/[...nextauth]/route";

// Sabit Misafir ID (route.ts ile aynı olmalı)
const GUEST_ID = "guest-uuid-unique-12345";

interface SessionUser {
  id: string;
  email?: string | null;
  name?: string | null;
}

/**
 * Misafir kullanıcısının veritabanında fiziksel olarak var olduğundan emin olur.
 */
async function ensureUserExists(userId: string) {
  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user && userId === GUEST_ID) {
    await prisma.user.create({
      data: {
        id: GUEST_ID,
        email: "guest@proje.com",
        password: "GUEST_PASSWORD_NO_ACCESS", 
        role: "USER",
      }
    });
  }
}

async function getAuthenticatedUser(): Promise<string | null> {
  const session = await getServerSession(authOptions);
  const user = session?.user as SessionUser | undefined;
  
  if (!user?.id) return null;
  return user.id;
}

export async function createNewTask(data: { titel: string; [key: string]: unknown }) {
  try {
    const userId = await getAuthenticatedUser();
    
    if (!userId) {
      return { success: false, error: "Niet ingelogd. Log opnieuw in." };
    }

    // Misafir ise DB'de kullanıcıyı oluştur/kontrol et
    await ensureUserExists(userId);

    await prisma.task.create({
      data: {
        title: data.titel,
        description: JSON.stringify(data), 
        userId: userId, 
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Create Error:", error);
    return { success: false, error: "Fout bij aanmaken" };
  }
}

export async function deleteTask(id: string) {
  try {
    const userId = await getAuthenticatedUser();
    if (!userId) return { success: false, error: "Niet geautoriseerd" };

    await prisma.task.delete({
      where: { 
        id: id,
        userId: userId 
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Delete Error:", error);
    return { success: false, error: "Verwijderen mislukt" };
  }
}

export async function updateTaskContent(id: string, fullData: { [key: string]: unknown }) {
  try {
    const userId = await getAuthenticatedUser();
    if (!userId) return { success: false, error: "Geen sessie" };

    await prisma.task.update({
      where: { 
        id: id,
        userId: userId 
      },
      data: {
        description: JSON.stringify(fullData),
      },
    });
    
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Update Error:", error);
    return { success: false, error: "Update mislukt" };
  }
}