"use client";
import { useState, useEffect } from "react";
import { Textarea } from "@/components/ui/textarea";

export default function SmartField({ label, value, onSave, isReadOnly }: { label: string, value: string, onSave: (v: string) => void, isReadOnly: boolean }) {
  const [localValue, setLocalValue] = useState(value);
  useEffect(() => { setLocalValue(value); }, [value]);

  return (
    <div className="space-y-3 group mt-8">
      <label className={`text-[11px] font-black uppercase tracking-widest italic transition-opacity ${isReadOnly ? 'text-gray-500 opacity-50' : 'text-teal-500 opacity-70 group-focus-within:opacity-100'}`}>
        {label} {isReadOnly && "(BEVEILIGD)"}
      </label>
      <Textarea
        readOnly={isReadOnly}
        value={localValue || ""}
        onChange={(e) => {
          if (isReadOnly) return;
          setLocalValue(e.target.value);
          onSave(e.target.value);
        }}
        className={`bg-[#0b1233]/40 border-teal-500/20 min-h-[150px] text-teal-50 text-lg border-l-4 transition-all outline-none ${
          isReadOnly 
            ? 'cursor-not-allowed border-gray-500/20 opacity-60 grayscale' 
            : 'focus:border-l-fuchsia-500 border-l-teal-500/50 shadow-inner'
        }`}
        placeholder={isReadOnly ? "Log in om gegevens in te voeren..." : "Typ hier..."}
      />
    </div>
  );
}